    const body = new THREE.Mesh(bakeGrad(new RoundedBoxGeometry(1.22, 0.34, 0.52, 3, 0.025), 0x454c53, 0x30363c, { curve: 1.1 }), gradMatDS);
    body.position.y = 0.27;
