    if (caveLamp) caveLamp.intensity = 1.05 + 0.1 * Math.sin(wxTime.value * 9) + 0.05 * Math.sin(wxTime.value * 23);
    // 보물 모래밭: 오늘의 자리 반짝임 + 아주 가끔 펫이 스스로 발굴
    refreshDigState();
