    menuTip.style.display = 'block';
    menuTip.style.left = `${Math.max(6, Math.min(r.left + r.width / 2 - 40, window.innerWidth - 110))}px`;
    menuTip.style.top = `${Math.max(6, r.top - 30)}px`;
