    balloonMenu.style.display = 'none';
    ferryMenu.style.display = 'none';
    mapMenu.style.display = 'none';
    if (!pressAt) return;
    const moved = Math.hypot(e.clientX - pressAt.x, e.clientY - pressAt.y);
    const held = performance.now() - pressAt.t;
