                if (!out.jelly && inf.jelly && islandOf(inf.jx, inf.jz) < 0 && seabedHeight(inf.jx, inf.jz) < -2.2 && Math.hypot(inf.jx, inf.jz) < 68) out.jelly = { x: +inf.jx.toFixed(1), z: +inf.jz.toFixed(1) };
