    for (const w of [rider, q]) { if (w) { w.poiWalk = null; w.moonYaw = 0; w.moonH = 0; w.moonJumpV = undefined; w.moonDir = null; w.mover.rotation.set(0, w.mover.rotation.y, 0); } }   // 구면 자세 청산
    rider.swimming = false;
