    rocketRide = { p: rider, friend: q || null, t: 0, zg: 0, som: [{ cd: 6 + Math.random() * 6, t: 9 }, { cd: 10 + Math.random() * 6, t: 9 }] };
    ROCKET.padDir = -1; ROCKET.padDone = false; ROCKET.aiEvaT = 0;
