    const dx = SUB.x + rgX * side * 0.9 * SUB_K, dz = SUB.z + rgZ * side * 0.9 * SUB_K;
    q.mover.position.set(dx, waveYAt(dx, dz) + 0.02 - q.height * 0.45, dz);
    q.swimming = 'sea';
    q.mover.rotation.x = 0;
    q.mover.rotation.z = 0;
