    SUB.mode = Math.hypot(SUB.x - SUB_HOME.x, SUB.z - SUB_HOME.z) < 2 ? 'docked' : 'return';
    if (SUB.mode === 'docked') { SUB.x = SUB_HOME.x; SUB.z = SUB_HOME.z; subCollider.x = SUB.x; subCollider.z = SUB.z; subCollider.r = SUB_R; }
