// 도감 — { speciesId: { n, max } }
function fishdexRecord(sp, len) {
    let dex = {};
    try { dex = JSON.parse(localStorage.getItem('world-fishdex') || '{}'); } catch (e) {}
    const first = !dex[sp.id];
    const rec = dex[sp.id] || { n: 0, max: 0 };
    rec.n += 1;
    rec.max = Math.max(rec.max, len);
    dex[sp.id] = rec;
    try { localStorage.setItem('world-fishdex', JSON.stringify(dex)); worldSync('world-fishdex'); } catch (e) {}
    return first;
}
// 🕰️ 오프라인 정산 훅 (낚시) — 로그만: AI 어획은 라이브에서도 도감에 안 오른다 (19644와 동일
// 규칙 — 도감은 주인이 직접 낚은 것만). 조건 어종(밤/비/계절)은 부재 중 날씨를 모르니 제외.
function offlineFishHook(n, win) {
    const pool = FISH_SPECIES.filter((s) => s.rarity > 0 && !s.when);
    if (!pool.length) return null;
    const events = [];
    for (let i = 0; i < n; i++) {
        const w = pool.map((s) => (s.rarity === 1 ? 0.6 : s.rarity === 2 ? 0.3 : 0.1));
        let x = Math.random() * w.reduce((a, b) => a + b, 0);
        let sp = pool[0];
        for (let k = 0; k < pool.length; k++) { x -= w[k]; if (x <= 0) { sp = pool[k]; break; } }
        events.push({ t: randAwakeTime(win), text: `${OFFLINE_WHO()}가 혼자 낚시로 ${sp.ko}를 낚아 올렸다 🎣` });
    }
    if (!events.length) return null;
    return { events, summary: `물고기 ${events.length}마리 낚음` };
}
function fishFanfare() {   // 잡았다! 차임 — 5도 상승 두 음
    if (audioCtx.state !== 'running') return;
    for (const [f, t0] of [[660, 0], [990, 0.11]]) {
        const o = audioCtx.createOscillator();
        o.type = 'sine';
        o.frequency.value = f;
        const gn = audioCtx.createGain();
        gn.gain.setValueAtTime(0.0001, audioCtx.currentTime + t0);
        gn.gain.exponentialRampToValueAtTime(0.12, audioCtx.currentTime + t0 + 0.02);
        gn.gain.exponentialRampToValueAtTime(0.0001, audioCtx.currentTime + t0 + 0.22);
        o.connect(gn);
        gn.connect(sfxMaster);
        o.start(audioCtx.currentTime + t0);
        o.stop(audioCtx.currentTime + t0 + 0.25);
    }
}
