// TEMP DRINK LAB — ?drinklab: 음료 9종 × 마시기 0/1/2 격자 (검수용, 커밋 전 제거)
if (location.search.includes('drinklab')) {
    const _dl = new THREE.DirectionalLight(0xffffff, 1.6); _dl.position.set(4, 26, 12); scene.add(_dl);
    scene.add(new THREE.AmbientLight(0xffffff, 0.55));
    DRINKS.forEach((dk, i) => {
        for (let sp = 0; sp <= 2; sp++) {
            try {
                const g = makeDrinkGeos(dk, sp), grp = new THREE.Group();
                grp.add(new THREE.Mesh(g.opaque, gradMat));
                if (g.glass) grp.add(new THREE.Mesh(g.glass, glassMat));
                if (g.liquid) grp.add(new THREE.Mesh(g.liquid, liquidMat));
                if (g.liquidSoft) grp.add(new THREE.Mesh(g.liquidSoft, liquidSoftMat));
                grp.scale.setScalar(9);
                grp.position.set((sp - 1) * 1.12 + Math.floor(i / 5) * 4.5, 20.4 - (i % 5) * 1.15, 0);
                scene.add(grp);
            } catch (e) { console.error('drinklab', dk.id, sp, e); }
        }
    });
    scene.background = new THREE.Color(0xe9eef2);
    camera.position.set(2.3, 18.6, 8.6);
    controls.target.set(2.3, 18.6, 0);
    controls.update();
    window.__foodlab = { camera, renderer, scene, controls };   // 마우스로 돌려볼 수 있게 controls 유지
}
// TEMP FOOD LAB — ?foodlab: 9종 × 베어물기 0/1/2 격자 (검수용, 커밋 전 제거)
if (location.search.includes('foodlab')) {
    const _fl = new THREE.DirectionalLight(0xffffff, 1.6); _fl.position.set(4, 26, 12); scene.add(_fl);
    scene.add(new THREE.AmbientLight(0xffffff, 0.5));
    FOODS.forEach((f, i) => {
        for (let bt = 0; bt <= 2; bt++) {
            try {
                const m = new THREE.Mesh(makeFoodGeo(f, bt), gradMat);
                m.scale.setScalar(9);
                m.position.set((bt - 1) * 1.15 + Math.floor(i / 5) * 4.6, 21.2 - (i % 5) * 1.25, 0);
                scene.add(m);
            } catch (e) { console.error('foodlab', f.id, bt, e); }
        }
    });
    ['apple', 'eggplant', 'tomato', 'lemon'].forEach((t, i) => {   // 꼭지 있는 과일 검수 행
        for (let bt = 0; bt <= 2; bt++) {
            try {
                const m = new THREE.Mesh(makeFruitGeo(t, bt), gradMat);
                m.scale.setScalar(9);
                m.position.set((bt - 1) * 1.15 + 9.2, 21.2 - i * 1.25 + 0.5, 0);
                scene.add(m);
            } catch (e) { console.error('fruitlab', t, bt, e); }
        }
    });
    scene.background = new THREE.Color(0xe6eef4);
    camera.position.set(2.3, 18.8, 8.4);
    controls.target.set(2.3, 18.8, 0);
    controls.update();
    window.__foodlab = { camera, renderer, scene, controls };
}

refreshFruit();   // 🍎 과일 초기 매달기 — 레이아웃·소품이 다 선 뒤 1회
applyHouseLight();   // 💡 전등 초기 상태 (수동 저장 > 밤 자동)
loadGroundFruits();   // 낙과 복원 (시들 시간 지난 건 조용히 흙으로)
// ---- 🔄 버전 워치독: 폰 PWA/홈화면 웹뷰는 오래 살아서 새 배포를 모른다 — 화면에 복귀할 때
// world.js의 ETag를 HEAD로 재확인해 바뀌었으면 토스트 후 자동 새로고침. 데스크톱/테스트 서버처럼
// ETag가 없으면 조용히 무력화된다 (LAN HEAD 1회 = 무비용). ----
let buildTag = null;
async function fetchBuildTag() {
    try {
        const r = await fetch('js/world.js', { method: 'HEAD', cache: 'no-store' });
        return r.headers.get('etag') || r.headers.get('last-modified') || null;
    } catch (e) { return null; }
}
fetchBuildTag().then((t) => { buildTag = t; });
document.addEventListener('visibilitychange', async () => {
    if (document.visibilityState !== 'visible' || !buildTag) return;
    const t = await fetchBuildTag();
    if (t && t !== buildTag) {
        buildTag = t;   // 재진입 중복 방지
        showToast('🔄 새 버전이 도착했어요 — 새로고침합니다');
        setTimeout(() => location.reload(), 1400);
    }
});
